<script setup lang="ts">
import { ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { api } from '../api'
import { useAppStore } from '../stores/app'
import AppIcon from './AppIcon.vue'
const sessionCache=new Map<string,any>()
const props=defineProps<{term:string;sentence:string;conversationId:string;open:boolean;setup?:unknown}>();const emit=defineEmits<{close:[]}>();const store=useAppStore();const {t,locale}=useI18n()
const loading=ref(false);const data=ref<any>(null);const saved=ref(false);const error=ref('')
let requestVersion=0
function normalized(value:string){return value.normalize('NFC').trim().replace(/\s+/gu,' ')}
function cacheKey(){return JSON.stringify([normalized(props.term),normalized(props.sentence),props.setup||null,store.settings?.learning.targetLanguageCode||'',String(locale.value).toLowerCase()])}
function remember(key:string,value:any){if(sessionCache.size>=200)sessionCache.delete(sessionCache.keys().next().value!);sessionCache.set(key,value)}
watch(()=>[props.open,props.term,props.sentence,props.setup,store.settings?.learning.targetLanguageCode,locale.value],async()=>{const version=++requestVersion;if(!props.open||!props.term){loading.value=false;return}const key=cacheKey();const cached=sessionCache.get(key);saved.value=false;error.value='';if(cached){data.value=cached;loading.value=false;return}loading.value=true;data.value=null;try{const result=await api.post<{lookup:any}>('/lookup',{term:props.term,sentence:props.sentence,setup:props.setup});if(version!==requestVersion)return;remember(key,result.lookup);data.value=result.lookup}catch{if(version===requestVersion)error.value=t('common.operationFailed')}finally{if(version===requestVersion)loading.value=false}},{immediate:true})
async function save(){if(!data.value||!store.settings)return;await api.post('/words',{term:props.term,lemma:data.value.lemma,meaning:data.value.contextMeaning,language:store.settings.learning.targetLanguageCode,details:data.value,sourceSentence:props.sentence,conversationId:props.conversationId});saved.value=true;store.notify(t('lookup.saved'))}
</script>
<template><Transition name="drawer"><aside v-if="open" class="lookup"><header><div><p>{{t('lookup.title')}}</p><h2>{{term}}</h2></div><button :aria-label="t('common.close')" @click="emit('close')"><AppIcon name="close"/></button></header><div v-if="loading" class="lookup-loading"><span class="skeleton"></span><span class="skeleton"></span><span class="skeleton"></span></div><div v-else-if="error" class="lookup-error">{{error}}</div><div v-else-if="data" class="lookup-content"><div class="word-meta"><span>{{data.partOfSpeech}}</span><span v-if="data.pronunciation">{{data.pronunciation}}</span><span v-if="data.lemma&&data.lemma!==term">{{t('lookup.lemma')}} · {{data.lemma}}</span></div><section class="context-sense"><small>{{t('lookup.meaningHere')}}</small><strong>{{data.contextMeaning}}</strong><blockquote>{{sentence}}</blockquote></section><section v-if="data.forms?.length"><h3>{{t('lookup.forms')}}</h3><div class="forms"><span v-for="form in data.forms"><b>{{form.label}}</b>{{form.value}}</span></div></section><section><h3>{{t('lookup.meanings')}}</h3><article v-for="(sense,index) in data.senses"><em>{{Number(index)+1}}</em><div><b>{{sense.meaning}}</b><p>{{sense.example}}</p><small>{{sense.translation}}</small></div></article></section><section v-if="data.collocations?.length"><h3>{{t('lookup.collocations')}}</h3><div class="chips"><span v-for="item in data.collocations">{{item}}</span></div></section><section v-if="data.register||data.regionalNotes" class="usage"><h3>{{t('lookup.usage')}}</h3><p>{{data.register}} {{data.regionalNotes}}</p></section></div><footer><button class="btn primary" :disabled="loading||saved||!data" @click="save"><AppIcon :name="saved?'check':'plus'"/>{{saved?t('lookup.saved'):t('lookup.add')}}</button></footer></aside></Transition><Transition name="fade"><div v-if="open" class="lookup-backdrop" @click="emit('close')"></div></Transition></template>
<style scoped>
.lookup{position:fixed;inset:0 0 0 auto;width:390px;background:#fbfaf6;border-left:1px solid var(--line);z-index:60;box-shadow:-20px 0 55px rgba(29,34,28,.12);display:flex;flex-direction:column}.lookup header{padding:25px 24px 18px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:start}.lookup header p{font-size:11px;letter-spacing:.14em;color:var(--muted);margin:0 0 5px}.lookup h2{font-size:28px;margin:0}.lookup header button{border:0;background:transparent;color:var(--muted)}.lookup-content{padding:19px 24px 100px;overflow:auto}.word-meta{display:flex;gap:6px;flex-wrap:wrap}.word-meta span{font-size:11px;padding:4px 7px;border-radius:7px;background:#e9ece6;color:var(--green)}.context-sense{background:var(--green);color:white;border-radius:14px;padding:17px;margin:17px 0}.context-sense small{font-size:11px;letter-spacing:.12em;color:#bed4c9;display:block;margin-bottom:7px}.context-sense strong{font-size:14px;line-height:1.55;display:block}.context-sense blockquote{font-size:11px;line-height:1.6;margin:12px 0 0;padding-top:11px;border-top:1px solid rgba(255,255,255,.2);opacity:.72}.lookup section{margin:22px 0}.lookup h3{font-size:11px;letter-spacing:.13em;color:var(--muted);margin:0 0 11px}.forms{display:flex;gap:7px;flex-wrap:wrap}.forms span{font-size:11px;border:1px solid var(--line);border-radius:8px;padding:6px 8px}.forms b{font-size:11px;color:var(--muted);margin-right:5px}.lookup article{display:grid;grid-template-columns:22px 1fr;gap:6px;padding:11px 0;border-top:1px solid var(--line)}.lookup article em{font-size:11px;color:var(--muted);font-style:normal}.lookup article b{font-size:11px}.lookup article p{font-size:12px;margin:6px 0 3px;line-height:1.5}.lookup article small{font-size:11px;color:var(--muted)}.chips{display:flex;gap:6px;flex-wrap:wrap}.chips span{background:#eeeae0;border-radius:7px;padding:6px 8px;font-size:11px}.usage p{font-size:11px;line-height:1.65;color:var(--muted)}.lookup footer{position:absolute;bottom:0;left:0;right:0;padding:14px 24px 22px;background:linear-gradient(transparent,#fbfaf6 20%)}.lookup footer .btn{width:100%}.lookup-loading{padding:24px}.lookup-loading span{height:75px;display:block;margin-bottom:12px;border-radius:12px}.lookup-error{padding:30px;color:var(--red);font-size:12px}.lookup-backdrop{position:fixed;inset:0;background:rgba(25,29,24,.15);z-index:55}.drawer-enter-active,.drawer-leave-active{transition:.28s ease}.drawer-enter-from,.drawer-leave-to{transform:translateX(100%)}.fade-enter-active,.fade-leave-active{transition:.2s}.fade-enter-from,.fade-leave-to{opacity:0}@media(max-width:600px){.lookup{width:100%;top:10vh;border-radius:20px 20px 0 0}.lookup-backdrop{bottom:90%}}
</style>
